M.push(['poll','Reader poll',{html:'<p class="sub"><b>How this poll works.</b> One question. Your answer is sent through the site\'s form host (Netlify). I see the answer, not your name. It is not a scientific poll, and it is not perfectly anonymous: the host may keep technical details like an IP address. A browser can vote once; someone determined can still vote again. Counts below are updated by hand.</p><form id="pf" name="poll" method="POST" data-netlify="true"><fieldset><legend>What would help you most right now?</legend><label class="cb"><input type="radio" name="answer" value="Plain-language summaries"> Plain-language summaries</label><label class="cb"><input type="radio" name="answer" value="The original documents"> The original documents</label><label class="cb"><input type="radio" name="answer" value="Help speaking at a meeting"> Help speaking at a meeting</label><label class="cb"><input type="radio" name="answer" value="Dates and reminders"> Dates and reminders</label></fieldset><button class="btn primary" type="submit" id="pb">Vote</button><p id="pm2" class="sub" role="status"></p></form><div id="pr"></div>',init:function(h){var done=store.get('polled',0);var f=q(h,'#pf');if(done){q(h,'#pb').disabled=true;q(h,'#pm2').textContent='You already voted in this browser.'}f.onsubmit=function(e){e.preventDefault();var v=f.querySelector('input:checked');if(!v){q(h,'#pm2').textContent='Pick one.';return}var body='form-name=poll&answer='+encodeURIComponent(v.value);fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body}).then(function(r){if(!r.ok)throw 0;store.set('polled',1);q(h,'#pb').disabled=true;q(h,'#pm2').textContent='Thanks. Your answer was sent.'}).catch(function(){q(h,'#pm2').textContent='This works on the live site only.'})};S.load('poll').then(function(d){var t=(d.counts||[]).reduce(function(a,c){return a+c[1]},0);q(h,'#pr').innerHTML=t?'<h4>Results so far ('+t+' votes, '+esc(d.updated||'')+')</h4>'+d.counts.map(function(c){return'<p>'+esc(c[0])+': <b>'+c[1]+'</b><span style="display:block;height:8px;background:var(--navy,#2a7);width:'+Math.round(100*c[1]/t)+'%"></span></p>'}).join(''):'<p class="sub">No results to show yet.</p>'}).catch(function(){})}}]);
