M.push(['car','Carousel generator',{html:'<p class="sub">Separate slides with a blank line. The first line of each slide is large. Download each as a square picture. Check facts and add the source before posting.</p><label class="full">Slides<textarea id="cat" rows="7"></textarea></label><div id="cao"></div>',init:function(h){q(h,'#cat').value='Policy F-18 at a glance\nSource: Policy F-18, updated Mar 3, 2026\n\nData is kept 30 days\nUnless it is needed for an investigation. Section 1.4.1.2.\n\nWhat the Chief said\nThe Axon trial would start at 14 days. That is a statement, not yet a written term.\n\nRead it yourself\nsunprairiealpr.netlify.app';function wrap(c,t,x,y,w,lh){var W=t.split(' '),l='';W.forEach(function(k){var tt=l?l+' '+k:k;if(c.measureText(tt).width>w&&l){c.fillText(l,x,y);y+=lh;l=k}else l=tt});if(l){c.fillText(l,x,y);y+=lh}return y}function d(){var sl=q(h,'#cat').value.split(/\n\s*\n/).map(function(s){return s.trim()}).filter(Boolean);q(h,'#cao').innerHTML=sl.map(function(s,i){return'<div class="ecard"><canvas width="1080" height="1080" data-i="'+i+'" style="width:100%;max-width:320px;height:auto"></canvas><br><button class="btn ghost" data-d="'+i+'" type="button">Download slide '+(i+1)+'</button></div>'}).join('');qa(h,'canvas').forEach(function(cv){var c=cv.getContext('2d'),L=sl[+cv.dataset.i].split('\n'),n=sl.length,i=+cv.dataset.i;c.fillStyle='#0f1a17';c.fillRect(0,0,1080,1080);c.fillStyle='#f2c230';c.fillRect(70,90,120,10);c.textBaseline='top';c.fillStyle='#e6efeb';c.font='700 72px Arial';var y=wrap(c,L[0],70,150,940,88);c.font='400 40px Arial';c.fillStyle='#b9c9c3';wrap(c,L.slice(1).join(' '),70,y+30,940,54);c.fillStyle='#6fcfb2';c.font='700 32px Arial';c.fillText('Sun Prairie ALPR · independent & unofficial',70,960);c.fillStyle='#9db0a9';c.font='400 28px Arial';c.fillText('Not affiliated with the City or SPPD · '+(i+1)+'/'+n,70,1005)});qa(h,'[data-d]').forEach(function(b){b.onclick=function(){var cv=q(h,'canvas[data-i="'+b.dataset.d+'"]');cv.toBlob(function(bl){var a=document.createElement('a');a.href=URL.createObjectURL(bl);a.download='sp-alpr-slide-'+(+b.dataset.d+1)+'.png';document.body.appendChild(a);a.click();a.remove()})}})}q(h,'#cat').oninput=d;d()}}]);
