var G=[];
G.push(['tone','Respectful tone guide',V.check('tone','Hard questions can be asked kindly and still be clear.',['Name the document or action, not the person','Ask a question before you make a claim','Quote exactly or paraphrase fairly, and give the source','Say what you do not know','Avoid labels for people (“bad,” “corrupt”) unless a court or official finding says so','Thank them for answering, even if you still disagree','One ask per message','Read it aloud. Would you say it to their face?','Wait a day before sending anything written when you are upset'])]);
G.push(['council','Email-the-council checklist',V.check('ec','Before you send.',['Subject line names the topic and meeting date','Your name and that you are a resident (if you are)','One clear point or question','One source I can name','What I am asking them to do or answer','Nothing I cannot back up','Polite closing and a request for a reply','Copy kept for my records (my notes may become public)'])]);
var QB={'Retention':['What is the retention setting now, and where is it written?','Can a different number be set without a public vote?','What happens to data at the end of retention?'],'Audits':['Who reviews searches, and how often?','Is a reason and case number required for every search?','Can the public see an audit summary?'],'Sharing':['Which agencies can see the data, and under what agreement?','Is that agreement public?','Can federal agencies access it directly or through another agency?'],'Cost':['What is the full cost over the contract term, including fees?','What is not included in the estimate?','What does it cost to end early?'],'Process':['Which meeting will this be decided at?','When can residents comment?','Where will the final documents be posted?']};
G.push(['qbank','Question bank by topic',{html:'<p class="sub">Neutral questions anyone can ask. Pick a topic and copy the ones you want.</p><div class="chips" id="qbt"></div><div id="qbo"></div>',init:function(h){var K=Object.keys(QB);q(h,'#qbt').innerHTML=K.map(function(k){return'<button type="button" class="chip" data-k="'+k+'" aria-pressed="false">'+k+'</button>'}).join('');function set(k){qa(h,'.chip').forEach(function(b){b.setAttribute('aria-pressed',b.dataset.k===k)});q(h,'#qbo').innerHTML=QB[k].map(function(x,i){return'<div class="ecard"><p>'+esc(x)+'</p><button class="btn ghost" data-q="'+i+'" type="button">Copy</button></div>'}).join('');qa(h,'[data-q]').forEach(function(b){V.copy(b,function(){return QB[k][+b.dataset.q]})})}qa(h,'.chip').forEach(function(b){b.onclick=function(){set(b.dataset.k)}});set(K[0])}}]);
G.push(['civic','Civic skills',{html:'<p class="sub">Three skills this issue teaches.</p><div class="ecard"><b>Reading a contract or estimate</b><p>Look for the type (draft, quote, final), dates, total cost, data ownership, retention, access, audits and exit terms. See “How to read a contract” in Explainers.</p></div><div class="ecard"><b>Reading a budget line</b><p>Find the fiscal year, the department, the amount and whether it is one-time or yearly. Ask what is not included.</p></div><div class="ecard"><b>Reading an agenda</b><p>Find the item number, the action requested (receive, approve, refer), the packet page and the public comment rules. See the Agenda decoder in Meetings and process.</p></div>'}]);
G.push(['qr','Quarterly report template',V.builder({sub:'What a good public quarterly report could contain. Fill it in only if a report like this is published. It is a template, not a claim that one exists.',file:'quarterly-report-template.txt',fields:[['q','Quarter','text','e.g., Q1 2027'],['n','Number of cameras','text',''],['r','Retention setting in effect','text',''],['s','Number of searches','text',''],['h','Number of hits and number verified','text',''],['a','Audits done and results','area',''],['sh','Agencies with access','area',''],['c','Changes to policy this quarter','area','']],make:function(v){return'ALPR QUARTERLY REPORT: '+(v.q||'[quarter]')+'\n\nCameras in use: '+(v.n||'[ ]')+'\nRetention setting: '+(v.r||'[ ]')+'\nSearches: '+(v.s||'[ ]')+'\nHits / verified hits: '+(v.h||'[ ]')+'\nAudits and results: '+(v.a||'[ ]')+'\nAgencies with access: '+(v.sh||'[ ]')+'\nPolicy changes: '+(v.c||'[ ]')+'\n\nSources and method: [add]\n\nNote: This is a template from an independent, unofficial site. It is not a City or SPPD report.'}})]);
G.push(['ann','Annual report on this site',V.builder({sub:'A yearly review of what I learned and what I got wrong.',file:'annual-report.txt',fields:[['y','Year','text','2026'],['l','Biggest things learned','area',''],['c','Corrections made (count and examples)','area',''],['u','Questions still unanswered','area',''],['f','Funding and costs (say if none)','area',''],['n','Next year','area','']],make:function(v){return'ANNUAL REPORT '+(v.y||'')+': Sun Prairie ALPR (independent, unofficial)\n\nWhat I learned: '+(v.l||'')+'\nCorrections: '+(v.c||'')+'\nStill unanswered: '+(v.u||'')+'\nFunding and costs: '+(v.f||'None')+'\nNext year: '+(v.n||'')+'\n\n'+IND}})]);
G.push(['cap','Captions file maker',{html:'<p class="sub">Paste your video script. It makes a captions file (.srt) timed by speaking speed, so you can add captions without a recording tool. Check the timing against your video.</p><label class="full">Script (one caption per line, 12 words or fewer)<textarea id="ct2" rows="6"></textarea></label><label>Words per minute<input id="cw2" type="number" value="150"></label><pre class="out" id="co2"></pre><button class="btn ghost" id="cc2" type="button">Copy</button> <button class="btn ghost" id="cd2" type="button">Download .srt</button>',init:function(h){q(h,'#ct2').value='Here is what Policy F-18 says.\nData is kept 30 days.\nUnless it is needed for an investigation.\nSource: Policy F-18, section 1.4.1.2.';function ts(s){var ms=Math.round(s*1000),H=Math.floor(ms/36e5),M=Math.floor(ms%36e5/6e4),S2=Math.floor(ms%6e4/1e3),m=ms%1000;return('0'+H).slice(-2)+':'+('0'+M).slice(-2)+':'+('0'+S2).slice(-2)+','+('00'+m).slice(-3)}function t(){var wpm=+q(h,'#cw2').value||150,at=0,o=[];q(h,'#ct2').value.split('\n').filter(function(l){return l.trim()}).forEach(function(l,i){var w=(l.match(/\S+/g)||[]).length,d=Math.max(1.2,w*60/wpm);o.push((i+1)+'\n'+ts(at)+' --> '+ts(at+d)+'\n'+l.trim()+'\n');at+=d});return o.join('\n')}function u(){q(h,'#co2').textContent=t()}q(h,'#ct2').oninput=u;q(h,'#cw2').oninput=u;u();V.copy(q(h,'#cc2'),t);q(h,'#cd2').onclick=function(){S.dl('captions.srt',t())}}}]);
G.push(['plan','Social post planner',{html:'<p class="sub">A simple calendar list. Plan, then post by hand. Saved in this browser. Always check the fact and source before posting.</p><div class="grid2"><label>Date<input id="pd" type="date"></label><label>Where<select id="pw"><option>Instagram</option><option>Facebook</option><option>Newsletter</option></select></label><label class="full">Post text<textarea id="pt2" rows="2"></textarea></label><label class="full">Source<input id="ps"></label></div><button class="btn primary" id="pa" type="button">Add</button> <button class="btn ghost" id="pc" type="button">Copy plan</button><div id="pl"></div>',init:function(h){var L=store.get('plan',[]);function d(){L.sort(function(a,b){return a.d>b.d?1:-1});q(h,'#pl').innerHTML=L.map(function(x,i){return'<div class="ecard"><b>'+esc(x.d)+' · '+esc(x.w)+'</b><p>'+esc(x.t)+'</p><p class="sub">Source: '+esc(x.s||'(none yet)')+'</p><label class="cb"><input type="checkbox" data-p="'+i+'"'+(x.ok?' checked':'')+'> Posted</label> <button class="btn ghost" data-x="'+i+'" type="button">Remove</button></div>'}).join('');qa(h,'[data-p]').forEach(function(c){c.onchange=function(){L[+c.dataset.p].ok=c.checked;store.set('plan',L)}});qa(h,'[data-x]').forEach(function(c){c.onclick=function(){L.splice(+c.dataset.x,1);store.set('plan',L);d()}})}q(h,'#pa').onclick=function(){if(!q(h,'#pt2').value.trim())return;L.push({d:q(h,'#pd').value||'(no date)',w:q(h,'#pw').value,t:q(h,'#pt2').value,s:q(h,'#ps').value});store.set('plan',L);q(h,'#pt2').value='';q(h,'#ps').value='';d()};V.copy(q(h,'#pc'),function(){return L.map(function(x){return x.d+' · '+x.w+' · '+x.t+' (Source: '+x.s+')'}).join('\n')});d()}}]);
G.push(['deck','Slides from the data',{html:'<p class="sub">Builds a short slide set from the tracker numbers, promises and open questions. Print it with “landscape” and one slide per page, or save it as PDF from the print window.</p><button class="btn primary" id="dp" type="button">Print slides</button><div id="dk"></div>',init:function(h){S.load('tracker').then(function(d){var sl=[['Sun Prairie plate readers: what the documents say','Independent, unofficial. Not affiliated with the City or SPPD.'],['Key numbers','<ul>'+d.numbers.slice(0,6).map(function(n){return'<li><b>'+esc(n[0])+'</b> '+esc(n[1])+'</li>'}).join('')+'</ul>'],['Promises and statements','<ul>'+d.promises.slice(0,6).map(function(p){return'<li>'+esc(p[1])+' <i>('+esc(p[3])+')</i></li>'}).join('')+'</ul>'],['Open questions','<ul>'+d.unanswered.map(function(p){return'<li>'+esc(p[2])+'</li>'}).join('')+'</ul>'],['Where to read it','<p>sunprairiealpr.netlify.app</p><p>'+IND+'</p>']];q(h,'#dk').innerHTML=sl.map(function(s,i){return'<section class="ecard" style="page-break-after:always;min-height:260px"><h3>'+esc(s[0])+'</h3>'+s[1]+'</section>'}).join('');q(h,'#dp').onclick=function(){window.print()}})}}]);
G.push(['cap2','Time capsule',{html:'<p class="sub">A snapshot of how the issue looks today: the numbers, the dates, the promises and the open questions. Download it and keep it. In a year it shows what was known then.</p><button class="btn primary" id="tc" type="button">Download the time capsule</button>',init:function(h){q(h,'#tc').onclick=function(){S.load('tracker').then(function(d){var t='TIME CAPSULE: Sun Prairie plate reader issue\nSaved '+new Date().toDateString()+'\n'+IND+'\n\nNUMBERS\n'+d.numbers.map(function(n){return'- '+n[0]+': '+n[1]+' ('+n[3]+')'}).join('\n')+'\n\nTIMELINE\n'+d.timeline.map(function(x){return'- '+x[0]+': '+x[1]}).join('\n')+'\n\nPROMISES AND STATEMENTS\n'+d.promises.map(function(p){return'- '+p[0]+' ('+p[2]+'): '+p[1]+' [status: '+p[3]+']'}).join('\n')+'\n\nOPEN QUESTIONS\n'+d.unanswered.map(function(p){return'- Asked '+p[0]+' of '+p[1]+': '+p[2]}).join('\n');S.dl('sp-alpr-time-capsule.txt',t)})}}}]);
G.push(['issue1','Newsletter issue 1 (draft)',{html:'<p class="sub">A first-issue draft using today\'s facts. Fill in the vote result after the meeting. Edit before sending, and send only to people who asked to hear from me.</p><pre class="out" id="i1"></pre><button class="btn ghost" id="i1c" type="button">Copy</button>',init:function(h){var t='Subject: Sun Prairie ALPR update, Issue 1\n\nHello,\n\nThanks for signing up. This is a short update on Sun Prairie\'s license plate readers. I share documents and sources and I do not take a side.\n\n1. The numbers. There are 9 cameras today. Policy F-18 (updated Mar 3, 2026) says plate data is kept 30 days unless needed for an investigation. Axon\'s draft, non-binding estimate is $235,388.97 over 10 years for 9 cameras and expires Nov 30.\n\n2. The vote. The Council\'s final 2027 budget vote is scheduled for Nov 17. [After the meeting: what the minutes show.]\n\n3. Still open. Whether the Axon item is part of that vote. Whether Flock audit logs are kept after Flock ends. The reply to records request PD-2399-2026.\n\nWhat is next: [dates]\n\nIf you see a mistake, reply and I will fix it and log it.\n\nZack\n\n'+IND+'\nTo stop getting these, reply with the word stop.';q(h,'#i1').textContent=t;V.copy(q(h,'#i1c'),function(){return t})}}]);
G.push(['actlog','Accessibility test log',{html:'<p class="sub">Record what you tested and what you did not. A log lets you say exactly what was checked, and when. Saved in this browser; copy it into the public Accessibility page when ready.</p><div class="grid2"><label>Date<input id="ad" type="date"></label><label>What I tested<input id="at2" placeholder="e.g., keyboard only, Tools page"></label><label>Result<select id="ar"><option>Passed</option><option>Problem found</option><option>Fixed</option><option>Not tested</option></select></label><label>Notes<input id="an"></label></div><button class="btn primary" id="aa" type="button">Add</button> <button class="btn ghost" id="ac" type="button">Copy log</button><ul id="al"></ul>',init:function(h){var L=store.get('actlog',[]);q(h,'#ad').value=new Date().toISOString().slice(0,10);function d(){q(h,'#al').innerHTML=L.map(function(x,i){return'<li>'+esc(x.d)+' · '+esc(x.t)+' · <b>'+esc(x.r)+'</b> · '+esc(x.n)+' <button class="btn ghost" data-x="'+i+'" type="button">Remove</button></li>'}).join('');qa(h,'[data-x]').forEach(function(b){b.onclick=function(){L.splice(+b.dataset.x,1);store.set('actlog',L);d()}})}q(h,'#aa').onclick=function(){if(!q(h,'#at2').value)return;L.unshift({d:q(h,'#ad').value,t:q(h,'#at2').value,r:q(h,'#ar').value,n:q(h,'#an').value});store.set('actlog',L);q(h,'#at2').value='';q(h,'#an').value='';d()};V.copy(q(h,'#ac'),function(){return L.map(function(x){return x.d+' · '+x.t+' · '+x.r+' · '+x.n}).join('\n')});d()}}]);
